"""Prepare review evidence only. Does not write the runtime bank."""
import copy, json, pathlib
ROOT = pathlib.Path(__file__).resolve().parents[3]
OUT = pathlib.Path(__file__).resolve().parent
def read(p): return json.loads(p.read_text(encoding='utf-8'))
def save(name, value): (OUT/name).write_text(json.dumps(value, ensure_ascii=False, indent=2)+'\n', encoding='utf-8')
before=read(OUT/'questions.before.json'); by={q['id']:q for q in before}
after={i:copy.deepcopy(by[i]) for i in [591,600,612,628]}
def replace(q, field, old, new):
    assert q[field].count(old)==1,(q['id'],field,old)
    q[field]=q[field].replace(old,new)
replace(after[591],'question','contains an unpatched vulnerability','contains an unpatched software flaw')
replace(after[591],'question_th','มีช่องโหว่ที่ยังไม่ได้รับการแพตช์ซึ่งเปิดทาง','มีข้อบกพร่องในซอฟต์แวร์ที่ยังไม่ได้รับการแพตช์ซึ่งเปิดทาง')
q=after[600]; r=q['explanation_detail']['incorrect'][0]; assert r['letter']=='B'
for lang,new in [('en','An SOP gives repeatable operational steps for a specified activity, rather than the structure for an enterprise-wide cybersecurity program.'),('th','ระเบียบปฏิบัติประจำกำหนดขั้นตอนการปฏิบัติงานที่ทำซ้ำได้สำหรับกิจกรรมเฉพาะ ไม่ใช่โครงสร้างของโปรแกรมความมั่นคงปลอดภัยทั้งองค์กร')]:
    old=r['text_'+lang]; replace(q,'explanation' if lang=='en' else 'explanation_th',old,new); r['text_'+lang]=new
q=after[612]; q['options_th'][2]=q['options_th'][2].replace('ที่กำกับดูแล','ที่ได้รับมอบหมายให้กำกับดูแล'); assert q['options_th']!=by[612]['options_th']
q=after[628]
q['options'][2]='45 minutes (from automated alert detection at 10:00 to completion of initial alert triage at 10:45)'
q['options_th'][2]='45 นาที (นับจากเวลาที่ระบบแจ้งเตือนเวลา 10:00 น. จนถึงเวลาที่นักวิเคราะห์คัดกรองการแจ้งเตือนเบื้องต้นเสร็จสิ้นเวลา 10:45 น.)'
r=next(x for x in q['explanation_detail']['incorrect'] if x['letter']=='C')
for lang,new in [('en','The 45 minutes run from alert generation to completion of initial triage, including any queueing and processing time; they are not compromise-to-detection time.'),('th','ช่วง 45 นาทีเริ่มจากการสร้างแจ้งเตือนจนคัดกรองเบื้องต้นเสร็จสิ้น รวมเวลารอและเวลาปฏิบัติงานที่เกิดขึ้น ไม่ใช่ช่วงเวลาจากการถูกเจาะถึงตรวจพบ')]:
    old=r['text_'+lang]; replace(q,'explanation' if lang=='en' else 'explanation_th',old,new); r['text_'+lang]=new
why={591:'Removes the answer label from both stems without changing the exploitable-flaw concept or scenario facts.',600:'Corrects an over-narrow SOP description; repeats the same corrected rationale in flat and structured EN/TH representations.',612:'Restores the existing English designated-role qualifier in Thai option C; does not grant any new authority or change the role.',628:'Aligns distractor C and its rationale to the triage-completion milestone already stated in both stems; detection remains 08:00–10:00.'}
safe=[dict(id=i,classification='SAFE',justification=why[i],fields={k:dict(before=by[i][k],after=v) for k,v in q.items() if v!=by[i][k]}) for i,q in after.items()]
save('safe-change-proposals.json',safe)
deferred=read(ROOT/'artifacts/qa/question-bank-academic-signoff/deferred-proposed-revisions.json')
held_drafts={i:copy.deepcopy(by[i]) for i in [614,627]}
q=held_drafts[614]
q['options'][2]='It is a purely qualitative assessment because the final scores should be interpreted only as descriptive labels rather than as numerical rankings'
q['options_th'][2]='เป็นการประเมินเชิงคุณภาพล้วน เพราะควรตีความคะแนนสุดท้ายเป็นเพียงคำบรรยายระดับความเสี่ยง ไม่ใช่การจัดอันดับด้วยตัวเลข'
r=next(x for x in q['explanation_detail']['incorrect'] if x['letter']=='C')
for lang,new in [('en','The method uses numerical ordinal scores to rank relative risk, so semi-quantitative is more precise than purely qualitative. Multiplication does not turn those ordinal scores into financial measurements with meaningful ratios.'),('th','วิธีนี้ใช้คะแนนตัวเลขเชิงอันดับเพื่อจัดระดับความเสี่ยงเปรียบเทียบ จึงเรียกว่ากึ่งเชิงปริมาณได้ตรงกว่าการประเมินเชิงคุณภาพล้วน การคูณไม่ได้เปลี่ยนคะแนนเชิงอันดับให้เป็นค่าความเสียหายทางการเงินที่เปรียบเทียบเป็นอัตราส่วนได้อย่างมีความหมาย')]:
    old=r['text_'+lang];replace(q,'explanation' if lang=='en' else 'explanation_th',old,new);r['text_'+lang]=new
q=held_drafts[627]
drafts={
 'A':('They need to be expressed as a percentage of inbound traffic, because the blocked percentage by itself demonstrates business-risk reduction.','ต้องแสดงเป็นร้อยละของทราฟฟิกขาเข้า เพราะร้อยละที่ถูกบล็อกเพียงอย่างเดียวแสดงได้ว่าความเสี่ยงทางธุรกิจลดลง','A blocked-traffic percentage adds a denominator but does not by itself establish reduced business risk. Interpretation still needs scope, exposure, control objectives and limitations.','ร้อยละของทราฟฟิกที่ถูกบล็อกเพิ่มตัวส่วนให้การวัด แต่เพียงเท่านี้ยังยืนยันไม่ได้ว่าความเสี่ยงทางธุรกิจลดลง การตีความยังต้องอาศัยขอบเขต ความเสี่ยงที่เผชิญ วัตถุประสงค์ของมาตรการ และข้อจำกัด'),
 'B':('They need a month-to-month comparison, because a rising count by itself demonstrates improvement in security posture.','ต้องเปรียบเทียบกับเดือนก่อน เพราะจำนวนที่เพิ่มขึ้นเพียงอย่างเดียวแสดงได้ว่าระดับความปลอดภัยดีขึ้น','A trend can be useful, but a rising count may reflect changed attack volume, monitoring scope or detection rules. It does not alone demonstrate improved protection.','แนวโน้มมีประโยชน์ได้ แต่จำนวนที่เพิ่มขึ้นอาจเกิดจากปริมาณการโจมตี ขอบเขตการเฝ้าระวัง หรือกฎตรวจจับที่เปลี่ยนไป จึงไม่ได้แสดงว่าการปกป้องดีขึ้นด้วยตัวมันเอง'),
 'D':('They need to be converted to a monetary value by treating each blocked scan as an equivalent prevented loss.','ต้องแปลงเป็นมูลค่าเงินโดยถือว่าการสแกนที่ถูกบล็อกแต่ละครั้งป้องกันความเสียหายได้เท่ากัน','A blocked scan is not evidence of an equivalent prevented loss. Financial estimates require a justified risk model and assumptions; multiplying this count by a fixed loss value supplies neither.','การสแกนที่ถูกบล็อกไม่ได้เป็นหลักฐานว่าป้องกันความเสียหายได้เท่ากันทุกครั้ง การประมาณมูลค่าต้องมีแบบจำลองความเสี่ยงและสมมติฐานที่อธิบายได้ การคูณจำนวนนี้ด้วยค่าความเสียหายคงที่ยังไม่ได้ให้หลักฐานดังกล่าว')}
for letter,(en,th,ren,rth) in drafts.items():
    j='ABCD'.index(letter);q['options'][j]=en;q['options_th'][j]=th
    r=next(x for x in q['explanation_detail']['incorrect'] if x['letter']==letter)
    for lang,new in [('en',ren),('th',rth)]:
        old=r['text_'+lang];replace(q,'explanation' if lang=='en' else 'explanation_th',old,new);r['text_'+lang]=new
reviews={
591:('1.2','C is the exploitable vulnerability; A asset, B threat and D impact do not name the software flaw.','Same classification target; cue removed.','R05/L03'),
600:('1.3','A framework structures the program. B SOP describes repeatable activity steps; C AUP governs use; D guideline provides narrower advice. All four rationale letters match.','Same framework/SOP distinction; correct reasoning and other distractors retained.','R06/R09/L04'),
612:('2.1','C designated business owner best fits supplied payroll risk authority. A auditor maintains independence; B analyst supplies evidence; D vendor advises, neither is assigned business authority.','Same designated-role target; Thai parity only.','R06'),
614:('2.1','D semi-quantitative ranking fits ordinal 1–5 bins. A/B financial or quantitative interpretations confuse scoring with measured quantities. C invented international ban is false and implausible; its rationale correctly rejects it.','Replacing C changes distractor plausibility and assessment difficulty; requires new bilingual option/rationale approval.','R05'),
627:('2.4','C raw count lacks decision context; A Layer-2-only claim, B blanket legal prohibition and D CPU multiplier are false. Explanations reject those actual claims but cannot repair their implausibility.','Replacing A/B/D materially changes discrimination even if C stays the key.','R11'),
628:('2.4','B 2h is compromise-to-detection. A includes containment, C alert-to-triage-completion and D detection-to-isolation are different intervals. Correct and wrong A/D reasoning retained.','Same TTD endpoint arithmetic; no new metric definition.','R11/R12'),
619:('2.2','C is plausible for bare fixed-site readiness; A warm has installed IT, B hot operational equipment, D mobile is transportable. No offered site label proves five-day RTO or cheapest compliant recovery. Existing assurance remains unaccepted.','Proposal narrows cost/RTO satisfaction to readiness classification; original target needs validated procurement, restore, dependency and cost evidence.','R10'),
629:('2.4','A containment milestone is defensible only with an explicit locally defined interval. B/C/D later investigation/recovery/reporting activities do not establish the proposed initial-containment endpoint; neither does current universal MTTR wording.','Proposal adds local SLA clock/mean semantics and completed-action wording. All rationales must use that definition rather than claim a universal Respond endpoint.','R11/R12'),
630:('2.4','D is the intended snapshot-versus-timeliness distinction, but current velocity wording overclaims; no option is fully precise. A/B/C misinterpret the denominators/measurement purpose.','Proposal supplies asset and finding cohorts, replaces all choices and their reasoning. D is conditional on human-approved revised item, not accepted as an unqualified current key.','R11'),
637:('2.2','D is the strongest active-active synchronous candidate among recovery alternatives A/B/C, but its label does not guarantee zero loss or under-15-minute service restoration. Current explanations overstate assurance.','Proposal changes guaranteed compliance to candidate requiring validation; also resolves EN under15 versus TH at-most15 and near-zero versus zero parity. Hold coherent revision, not isolated cosmetic edits.','R10')}
matrix=[]
for i in [591,600,612,614,627,628,619,629,630,637]:
    obj,keycheck,target,source=reviews[i]
    row=dict(id=i,domain=by[i]['dom'],objective=obj,key='ABCD'[by[i]['correct_idx']],classification='SAFE' if i in after else 'SUBSTANTIVE',key_and_options_review=keycheck,target_assessment=target,source_refs=source,before=by[i],after=after.get(i,by[i]),applied=i in after)
    if str(i) in deferred: row['unapplied_proposal']=deferred[str(i)]
    if i==614:row['unapplied_proposal']={'en':'Replace only distractor C with a plausible misunderstanding of ordinal scales, then align C rationale. Preserve D as proposed key; do not introduce invented standards or claim all numeric scoring is quantitative. Draft option text requires human approval before integration.','th':'เสนอให้แทนตัวลวง C ด้วยความเข้าใจคลาดเคลื่อนที่เป็นไปได้เกี่ยวกับระดับคะแนนเชิงอันดับ และปรับเหตุผลของ C ให้สอดคล้อง คง D เป็นเฉลยที่เสนอ ห้ามอ้างมาตรฐานที่สมมติขึ้นหรือเหมารวมว่าคะแนนตัวเลขเป็นการวัดเชิงปริมาณทั้งหมด ต้องอนุมัติข้อความตัวเลือกก่อนนำเข้า'}
    if i==627:row['unapplied_proposal']={'en':'Replace A/B/D with distinct plausible errors about measurement purpose, scope or comparability. Retain the board decision context and C as proposed key; reassess every alternative and rationale together before approval. No replacement option wording is approved by this report.','th':'เสนอให้แทน A/B/D ด้วยความเข้าใจคลาดเคลื่อนที่เป็นไปได้และแยกจากกันเกี่ยวกับวัตถุประสงค์ ขอบเขต หรือความเทียบเคียงได้ของการวัด คงบริบทการตัดสินใจของคณะกรรมการและ C เป็นเฉลยที่เสนอ ต้องประเมินทุกตัวเลือกและเหตุผลร่วมกันก่อนอนุมัติ รายงานนี้ยังไม่อนุมัติข้อความตัวเลือกทดแทน'}
    if i in held_drafts:
        draft=held_drafts[i]
        row['proposed_after_record_not_applied']=draft
        row['proposed_fields_not_applied']={k:dict(before=by[i][k],after=v) for k,v in draft.items() if v!=by[i][k]}
        row['draft_review']='Phase2.5 concrete draft of Phase2 revision direction. Same stem/target and proposed key; distractor redesign is SUBSTANTIVE. Q614 C confuses descriptive labels with ordinal ranking. Q627 A overclaims a ratio, B a trend and D equivalent prevented loss; none proves the contextual business-risk conclusion in C. All other current options/rationales retained. Human academic and qualified bilingual review required.'
    matrix.append(row)
save('ten-question-review.json',matrix)
slots=read(OUT/'expansion-slots.before.json'); original=copy.deepcopy(slots)
changes={
1044:dict(target='Apply a supplied ordinary retention schedule',context='Determine disposition from an explicitly supplied retention period and trigger; no erasure request, legal hold or exceptional preservation condition.',overlap='1022 tests an incident/legal-hold exception. 1045 tests category-scoped erasure conflicts. This slot applies the ordinary schedule only.',source_limit='Read D1 sum 431–451, Data Retention. Supply the rule; do not invent a statutory period or universal deletion requirement.'),
1045:dict(target='Scope an erasure request against supplied retention obligations',context='Separate explicitly defined record categories eligible for erasure from categories subject to a stated retention requirement; avoid blanket deletion or blanket retention.',overlap='1044 applies an ordinary schedule without competing requests; 1022 concerns incident preservation. This target is category-scoped rights-request disposition.',source_limit='D1 sum 453–468, Right to Be Forgotten, with 431–451 retention. Supply the governing requirement and affected categories; no unsupported named-law exceptions or legal advice.'),
1046:dict(target='Purpose-compatible use of personal data',context='An authorized secondary use conflicts with the explicitly stated original purpose and governing rule while confidentiality and access boundaries remain intact.',overlap='1043 concerns unnecessary collection; 585 concerns masking. Assess permitted purpose of use, not minimization, confidentiality failure or accountability logging.',source={'path':'ISC2 Update 2026/Domain 1/Domain 1.md','line':136,'heading':'4.2 Privacy — ความเป็นส่วนตัว'},source_limit='Read Domain 1.md 136–146 Privacy; corrected from the Accountability heading at 142. Do not imply every secondary use is forbidden; supply the purpose rule.'),
1051:dict(target='Constrained comparison of risk-treatment evidence',context='Compare supplied costs and expected loss reductions on a common time horizon and unit basis, subject to explicit binding legal, safety or policy constraints; identify the defensible comparison rather than a universal cost-only acceptance rule.',overlap='1049 calculates a single-loss estimate; 1050 annualizes loss. This slot interprets comparable treatment evidence under constraints. 1065 compares metric cohorts rather than investment choices.',source={'path':'ISC2 Update 2026/Domain 1/Script - DOMAIN 1.txt','line':175,'heading':'00:41:59–00:44:46 — risk acceptance cost example (read through line 182)'},source_limit='Read transcript 175–182 in full, not fragment 181 alone. Its simplified cost comparison is not a universal acceptance rule. Supplement Domain 1.md governance 231–252 and NIST SP800-30r1 §2.3.2; supply common horizon, cost categories, benefits and binding constraints. No advanced finance or unstated ROI formula.'),
1071:dict(target='Prospective scope of a group-wide permission change',context='Identify all affected principals before changing a shared group permission. Membership is fixed; only permissions from that single flat group apply. No nesting, overrides or deny-precedence rules.',overlap='648/649 concern mover cleanup and verification; 658 read-only PoLP; 665 existing multiple-role effective rights; 663 identifies RBAC. This is prospective blast radius of one shared permission edit, not cleanup or model recall.',source_limit='D3 surm 564–566 Group-Based Access supports assigning permissions to groups. Microsoft access-control overview corroborates member permissions. Explicit simplified model is required; do not generalize to nested inheritance or vendor-specific precedence.'),
1078:dict(target='Select the time-synchronization service function',context='Clocks are explicitly unsynchronized while event collection and forwarding work; an approved time source is available. Assess NTP function, not secure remote administration or default-port recall.',overlap='1012/1034 concern missing telemetry/forwarding. This slot repairs clock alignment with working transport; it must not become another logging-pipeline repair.',source={'path':'ISC2 Update 2026/Domain 4/D4 surm.md','line':187,'heading':'2.11 Applications and Protocols — Time sync / NTP row'},source_limit='Read application table 166–190, especially NTP row187. Time synchronization supports event correlation; NTP alone does not guarantee authenticity, integrity or trustworthy logs.'),
1080:dict(target='Policy-triggered reevaluation during ongoing resource access',context='Apply an explicit resource policy after a verified relevant device-posture/context change during access. VPN admission remains intact; the supplied policy defines the reevaluation and response.',overlap='689 concerns VPN/firewall architecture; 702 role/dataset separation; 664 ABAC label; 668 uncertain AI alert; 651 offboarding session termination. This is ongoing access reevaluation on verified change under an explicit policy.',source_limit='D4 surm 268–280 Zero Trust and D4 sum418 introduce context-based verification. NIST SP800-207 §2.1 tenet6 supports reevaluation during communication. Do not assert universal automatic denial, fixed reauthentication frequency or instant revocation.'),
1082:dict(target='Bulk confidentiality after a shared session key is established',context='Select the symmetric-encryption role for bulk data confidentiality after the shared/session key has already been established and protected; key establishment is explicitly outside the decision.',overlap='1007 selects the recipient public key to encrypt a short message; 1010 concerns PQC dependencies; 1083 signature key roles. This slot concerns bulk encryption with an already-established shared key. Do not mix session establishment with bulk protection in a hybrid-protocol choice.',source_limit='D5 sum61–97 Symmetric Encryption and session-key use; FIPS197 corroborates AES as a symmetric block cipher. No universal speed comparison, benchmark, key-length trivia or claim that confidentiality alone authenticates a sender.')}
